export const Schema = z.object({
    轮回界域: z.object({
        帖子: z.record(z.string().describe('帖子ID'), z.object({
            标题: z.string(),
            作者: z.string(),
            时间: z.string().describe('发布或回复时间，格式 YYYY-MM-DD HH:MM'),
            内容: z.string(),
            回帖: z.record(z.string().describe('回帖ID'), z.object({
                作者: z.string(),
                时间: z.string().describe('格式 YYYY-MM-DD HH:MM'),
                内容: z.string(),
            })),
        })),
        好友: z.record(z.string().describe('好友界域名，全界域唯一'), z.object({
            添加时间: z.string().describe('格式 YYYY-MM-DD HH:MM'),
            私聊: z.record(z.string().describe('私聊消息ID'), z.object({
                作者: z.string().describe('发送者界域名，为玩家本人或该好友'),
                时间: z.string().describe('格式 YYYY-MM-DD HH:MM'),
                内容: z.string(),
            })),
        })),
    }),
});
